// Package catalog loads `.noml` translation catalogs for the Nolang toolchain.
//
// It is deliberately a separate package from `i18n`: `i18n` must stay free of
// dependencies so every compiler package can import it without creating a cycle,
// while the catalog reader needs the `.noml` parser that lives in `package`.
//
// Layout:
//
//	src/i18n/catalog/locales/en.noml      generated by cmd/genen (translator template)
//	src/i18n/catalog/locales/zh-cn.noml   hand-maintained translations
//	<project>/locales/<tag>.noml          optional per-project override
//
// English has no runtime catalog: `i18n.T` returns the inline default when the
// language is English, so en.noml is never read by the binary. It exists so
// translators have a complete, sorted template and so the gate can prove it is
// in sync with the source.
package catalog

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/lizongying/nolang/i18n"
	pkg "github.com/lizongying/nolang/package"
)

// LocaleDirName is the directory (relative to a project root) that may hold
// `<tag>.noml` overrides.
const LocaleDirName = "locales"

// EnCatalogHeader is the fixed preamble of the generated en.noml. The generator
// and the freshness gate both render through RenderEn, so this text exists once.
const EnCatalogHeader = "; Nolang message catalog: en\n" +
	"; GENERATED by `make i18n` from i18n.T / i18n.P / i18n.Errorf call sites.\n" +
	"; Do not edit by hand: edit the call site, then run `make i18n`.\n"

// RenderEn renders the English catalog document from id -> inline text, sorted
// by ID for a byte-stable result.
func RenderEn(entries map[string]string) string {
	var sb strings.Builder
	sb.WriteString(EnCatalogHeader)
	sb.WriteString("{\n")
	writeEntries(&sb, entries)
	sb.WriteString("}\n")
	return sb.String()
}

func writeEntries(sb *strings.Builder, entries map[string]string) {
	ids := make([]string, 0, len(entries))
	for id := range entries {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	for _, id := range ids {
		sb.WriteString("  ")
		sb.WriteString(pkg.NomlQuote(id))
		sb.WriteString(": ")
		sb.WriteString(pkg.NomlQuoteValue(entries[id]))
		sb.WriteString("\n")
	}
}

// DocCatalogSuffix marks a doc catalog: `locales/<tag>-doc.noml`. Doc catalogs
// are a separate FILE, not a section of the message catalog, because the two
// have different key namespaces and different ownership rules:
//
//   - message keys are 8-character base36 IDs assigned by the generator and are
//     fully regenerated on every `make i18n`;
//   - doc keys are the anchors an author wrote in the source (`args.get`), and a
//     value is SEEDED once and then preserved, because its source text lives in
//     a comment rather than at a Go call site.
//
// Keeping them apart lets each gate stay exact: `TestLocaleKeysAndVerbs` can keep
// demanding `^[0-9a-z]{8}$` for every message key, and the doc gate can demand
// that every anchor in a doc catalog still exists in the source.
//
// The suffix is `-doc.noml`, not `.doc.noml`, because a file name in this tree
// follows the `.no` rule (lowercase letters, digits and single hyphens — see
// package.ValidateSourcePathName) and because two dots in one name is a shape
// nothing else here uses. Use DocCatalogName to build a name from a tag.
const DocCatalogSuffix = "-doc.noml"

// DocCatalogName returns the doc-catalog file name for tag.
//
// The tag is lowercased because a file name is lowercase-only by the `.no`
// naming rule: `zh-CN` is the tag a user types and the key of the message
// catalog, but its doc catalog is `zh-cn-doc.noml`.
func DocCatalogName(tag string) string {
	return strings.ToLower(tag) + DocCatalogSuffix
}

// IsDocCatalogName reports whether a file name is a doc catalog.
func IsDocCatalogName(name string) bool {
	return strings.HasSuffix(name, DocCatalogSuffix)
}

// AliasCatalogSuffix marks an ALIAS catalog: `locales/<tag>-alias.noml`. An
// alias catalog gives every std function/method its doc anchor a localized
// display name ("别名") plus the keystroke columns completion filters on. The
// value is an OBJECT, not a string:
//
//	'args.get': {
//	  alias: ['获取参数']
//	  keys: 'hqcs'
//	  enkeys: 'g'
//	  pinyin: 'huoqucanshu'
//	}
//
// The keystroke columns exist because the identifier is English while the
// display name is not: someone who knows the function as 获取参数 cannot spell
// `get`. Typing the name's initials (keys), the identifier's initials (enkeys),
// or — for Chinese — the full pinyin/zhuyin keystrokes lets completion propose
// the identifier. All four columns are ASCII `[a-z0-9]` because completion
// compares them byte for byte against what the editor reports as typed text.
//
// Alias and doc catalogs share the key namespace (the author-written anchor)
// but not the value semantics, so they live in separate files:
//
//   - doc values are translations of a whole comment block and are pruned
//     against every anchored block in the tree (hover can point at any of them);
//   - alias values are one-lined rows over the stable, machine-checkable domain
//     of `src/std` anchors, which is why en-alias.noml is required to be
//     COMPLETE and the other locales are compared against it key for key.
const AliasCatalogSuffix = "-alias.noml"

// AliasFields are the member names of an alias row, in render order. They are
// exported so the gate can assert "these and nothing else".
const (
	AliasFieldAlias  = "alias"
	AliasFieldKeys   = "keys"
	AliasFieldEnKeys = "enkeys"
	AliasFieldPinyin = "pinyin"
	AliasFieldZhuyin = "zhuyin"
)

// AliasRequiredFields are the members every row must carry: without a display
// name there is nothing to show, and keys/enkeys are the minimum a user can
// type. pinyin and zhuyin are locale-specific and optional.
var AliasRequiredFields = []string{AliasFieldAlias, AliasFieldKeys, AliasFieldEnKeys}

// AliasCatalogName returns the alias-catalog file name for tag. Like
// DocCatalogName it lowercases the tag, because a file name follows the `.no`
// naming rule (`zh-CN` is the tag, `zh-cn-alias.noml` is the file).
func AliasCatalogName(tag string) string {
	return strings.ToLower(tag) + AliasCatalogSuffix
}

// IsAliasCatalogName reports whether a file name is an alias catalog.
func IsAliasCatalogName(name string) bool {
	return strings.HasSuffix(name, AliasCatalogSuffix)
}

// AliasCatalogHeaderFor is the fixed preamble of a rendered alias catalog.
//
// The text is part of the byte comparison the freshness gate performs, so it is
// also the place a human is told what the columns mean — a translator editing
// one row sees the schema without opening the Go source.
func AliasCatalogHeaderFor(tag string) string {
	return "; Nolang alias catalog: " + tag + "\n" +
		"; Display names (别名) and keystroke columns for every std function/method,\n" +
		"; keyed by the same doc anchor its `; [label](#anchor)` comment uses, so an\n" +
		"; alias and its documentation block always agree on the key. One row per\n" +
		"; anchor, as an object:\n" +
		";\n" +
		";   alias:  ['获取参数']      display names; the first one is what hover shows\n" +
		";   keys:   'hqcs'          initials of the localized name — required\n" +
		";   enkeys: 'g'             initials of the identifier — required everywhere\n" +
		";   pinyin: 'huoqucanshu'   full pinyin keystrokes — zh-CN rows only\n" +
		";   zhuyin: 'fm32k6h0gj4'   zhuyin key positions (Dachen) — zh-TW rows only\n" +
		";\n" +
		"; keys, enkeys, pinyin and zhuyin are ASCII [a-z0-9]: completion compares\n" +
		"; them byte for byte against what the editor reports as typed, so a\n" +
		"; non-ASCII cell would silently never match. The identifier itself remains\n" +
		"; the only spelling that compiles — these columns only tell the completion\n" +
		"; provider which identifier the reader is reaching for. Keys must exist as\n" +
		"; an anchor in some src/std .no source, or the gate rejects the catalog;\n" +
		"; `make i18n -alias-missing` lists what is left.\n"
}

// RenderAlias renders an alias catalog, sorted by key. The output is
// deterministic down to the byte — anchors sorted, fields in a fixed order, an
// empty optional column omitted rather than written as '' — because both the
// generator and the freshness gate render through here, so "what `make i18n`
// writes" and "what the gate expects" cannot drift.
func RenderAlias(tag string, entries map[string]i18n.AliasEntry) string {
	var sb strings.Builder
	sb.WriteString(AliasCatalogHeaderFor(tag))
	sb.WriteString("{\n")
	anchors := make([]string, 0, len(entries))
	for anchor := range entries {
		anchors = append(anchors, anchor)
	}
	sort.Strings(anchors)
	for _, anchor := range anchors {
		e := entries[anchor]
		// A row with no display name carries nothing to show and cannot be
		// parsed back (alias must list at least one name), so it is skipped
		// here rather than rendered into a file the loader would reject.
		if len(e.Alias) == 0 {
			continue
		}
		sb.WriteString("  ")
		sb.WriteString(pkg.NomlQuote(anchor))
		sb.WriteString(": {\n")
		sb.WriteString("    ")
		sb.WriteString(AliasFieldAlias)
		sb.WriteString(": [")
		for i, name := range e.Alias {
			if i > 0 {
				sb.WriteString(", ")
			}
			sb.WriteString(pkg.NomlQuote(name))
		}
		sb.WriteString("]\n")
		writeAliasColumn(&sb, AliasFieldKeys, e.Keys)
		writeAliasColumn(&sb, AliasFieldEnKeys, e.EnKeys)
		writeAliasColumn(&sb, AliasFieldPinyin, e.Pinyin)
		writeAliasColumn(&sb, AliasFieldZhuyin, e.Zhuyin)
		sb.WriteString("  }\n")
	}
	sb.WriteString("}\n")
	return sb.String()
}

// writeAliasColumn writes one optional scalar member, or nothing when it is
// empty. pkg.NomlQuote (not NomlQuoteValue) is deliberate: a keystroke column
// has no newline, and NomlQuote cannot switch to a backtick block, which would
// break the one-member-per-line determinism the gate compares.
func writeAliasColumn(sb *strings.Builder, field, value string) {
	if value == "" {
		return
	}
	sb.WriteString("    ")
	sb.WriteString(field)
	sb.WriteString(": ")
	sb.WriteString(pkg.NomlQuote(value))
	sb.WriteString("\n")
}

// PruneAliasTranslations returns the alias table to render: the committed rows
// restricted to anchors the std sources still declare. Unlike doc catalogs
// nothing is ever seeded, and a row with no display name is dropped so a
// half-filled locale degrades to the identifier rather than a blank name.
func PruneAliasTranslations(scanned map[string]bool, existing map[string]i18n.AliasEntry) map[string]i18n.AliasEntry {
	out := make(map[string]i18n.AliasEntry, len(existing))
	for anchor, e := range existing {
		if !scanned[anchor] || len(e.Alias) == 0 {
			continue
		}
		out[anchor] = e
	}
	return out
}

// MissingAliasTranslations lists, sorted, the std anchors a locale has no
// alias for yet.
func MissingAliasTranslations(scanned map[string]bool, existing map[string]i18n.AliasEntry) []string {
	var out []string
	for anchor := range scanned {
		if _, ok := existing[anchor]; !ok {
			out = append(out, anchor)
		}
	}
	sort.Strings(out)
	return out
}

// DocCatalogHeaderFor is the fixed preamble of a rendered doc catalog.
//
// The text spells out the rule that makes this file unlike en.noml: it holds
// TRANSLATIONS ONLY. An anchor that is not in here falls back to the comment
// text in the .no source, which is exactly what an untranslated block should do.
// Seeding every anchor with its source text would fill the English catalog with
// Chinese, which is the failure mode en.noml was already fixed for.
func DocCatalogHeaderFor(tag string) string {
	return "; Nolang doc catalog: " + tag + "\n" +
		"; Source-comment translations, keyed by the anchor an author wrote in a\n" +
		"; trailing `[label](#anchor)` line. This file holds TRANSLATIONS ONLY: an\n" +
		"; anchor that is absent falls back to the comment text in the .no source, so\n" +
		"; untranslated blocks degrade to the author's language instead of shipping a\n" +
		"; copy of it here. Every key must still exist in some .no source, or the gate\n" +
		"; rejects it as an orphan.\n"
}

// RenderDoc renders a doc catalog, sorted by key.
func RenderDoc(tag string, entries map[string]string) string {
	var sb strings.Builder
	sb.WriteString(DocCatalogHeaderFor(tag))
	sb.WriteString("{\n")
	writeEntries(&sb, entries)
	sb.WriteString("}\n")
	return sb.String()
}

// PruneDocTranslations returns the doc table to render: the committed values,
// restricted to anchors that still exist in the source.
//
// Two deliberate choices, both different from message catalogs:
//
//   - a scanned anchor with no committed value is NOT seeded. The source text is
//     the author's language, and English is a translation target for it, so
//     seeding would put Chinese into en-doc.noml and, worse, would make the
//     catalog claim a translation that no one wrote.
//   - a committed value is preserved verbatim, even if the source comment was
//     reworded. The anchor, not the text, is the key, so rewording must not
//     orphan a translation.
//
// The generator and the freshness gate both call this, so "what `make i18n`
// writes" and "what the gate expects" cannot drift.
func PruneDocTranslations(scanned, existing map[string]string) map[string]string {
	if len(existing) == 0 {
		return nil
	}
	out := make(map[string]string, len(existing))
	for anchor, text := range existing {
		if _, ok := scanned[anchor]; !ok || text == "" {
			continue
		}
		out[anchor] = text
	}
	return out
}

// MissingDocTranslations lists, in sorted order, the anchors the source defines
// but a doc catalog does not translate yet. Used by the generator's report so a
// translator can see the remaining work without diffing two files.
func MissingDocTranslations(scanned, existing map[string]string) []string {
	var out []string
	for anchor := range scanned {
		if _, ok := existing[anchor]; !ok {
			out = append(out, anchor)
		}
	}
	sort.Strings(out)
	return out
}

// LocaleFileName returns the message-catalog file name for tag.
//
// Like DocCatalogName it lowercases the tag, because a file name in this tree
// follows the `.no` rule (lowercase letters, digits and single hyphens — see
// package.ValidateSourcePathName). The TAG keeps its conventional spelling
// (`zh-CN`), because that is what a user types and what Lang() reports; only the
// file is `zh-cn.noml`. Every read of a catalog file goes through this function,
// so "the tag" and "the file" cannot drift apart.
func LocaleFileName(tag string) string {
	return strings.ToLower(tag) + ".noml"
}

// alias maps a requested tag onto the tag whose file we actually ship. Chinese
// is split by script: Hans/plain "zh" resolve to the Simplified catalog, while
// Hant and the Traditional-script regions (TW/HK/MO) resolve to zh-TW.
//
// The lower-case file spellings are entries too: tagsInDir and embeddedTags see
// file names, not tags, so `zh-cn.noml` has to map back to the `zh-CN` tag that
// Lang() reports.
var alias = map[string]string{
	"zh":      "zh-CN",
	"zh-hans": "zh-CN",
	"zh-cn":   "zh-CN",
	"zh-hant": "zh-TW",
	"zh-tw":   "zh-TW",
	"zh-hk":   "zh-TW",
	"zh-mo":   "zh-TW",
}

// Options configures Init.
type Options struct {
	// Lang is the explicit tag from --lang. Empty with LangSet false means "not
	// requested".
	Lang    string
	LangSet bool
	// ProjectDirs are searched for `locales/<tag>.noml` before the embedded
	// files, most specific first.
	ProjectDirs []string
	// Env reads environment variables (nil = os.Getenv).
	Env func(string) string
	// Warn receives non-fatal notices.
	Warn func(msg string)
}

// Init resolves the language and installs its catalog. It is the only function
// the binaries need to call.
func Init(o Options) error {
	return i18n.Init(i18n.Options{
		Lang:      o.Lang,
		LangSet:   o.LangSet,
		Available: Available(o.ProjectDirs),
		Env:       o.Env,
		Warn:      o.Warn,
		Canonical: Canonical,
		Load: func(tag string) (map[string]string, error) {
			return Load(o.ProjectDirs, tag)
		},
		DocLoad: func(tag string) (map[string]string, error) {
			return LoadDoc(o.ProjectDirs, tag)
		},
		AliasLoad: func(tag string) (map[string]string, error) {
			return LoadAlias(o.ProjectDirs, tag)
		},
	})
}

// LoadDoc reads the doc catalog for tag: project `locales/<tag>-doc.noml` first,
// then the embedded copy. A tag with no doc catalog is not an error — it returns
// nil, nil so that `Doc` simply falls back to the source text.
//
// It resolves through Canonical for the same reason Load does: `zh` must find the
// `zh-CN` file, or a user who typed `--lang=zh` would get untranslated comments
// while messages were translated. The file name is built by DocCatalogName,
// which lowercases the tag (`zh-cn-doc.noml`).
func LoadDoc(projectDirs []string, tag string) (map[string]string, error) {
	tag = Canonical(tag)
	name := DocCatalogName(tag)
	for _, dir := range projectDirs {
		if dir == "" {
			continue
		}
		path := filepath.Join(dir, LocaleDirName, name)
		data, err := os.ReadFile(path)
		if err != nil {
			if os.IsNotExist(err) {
				continue
			}
			return nil, fmt.Errorf("i18n: reading %s: %w", path, err)
		}
		return parseCatalog(path, data)
	}

	path := "locales/" + name
	data, err := localesFS.ReadFile(path)
	if err != nil {
		// No doc catalog for this tag: untranslated, not broken.
		return nil, nil
	}
	return parseCatalog(path, data)
}

// LoadAlias reads the alias catalog for tag: project
// `locales/<tag>-alias.noml` first, then the embedded copy. A missing file is
// not an error — i18n.Alias then falls back to the identifier itself, exactly
// like Doc falling back to the source comment. Resolution goes through
// Canonical and the lower-cased file name for the same reasons as LoadDoc.
//
// An alias catalog obeys a stricter schema than the other two (every row is an
// object with alias/keys/enkeys), so a project override still written in the
// old flat format fails to parse: the whole language degrades to identifiers
// with a warning rather than half-loading a table nothing can read.
func LoadAlias(projectDirs []string, tag string) (map[string]i18n.AliasEntry, error) {
	tag = Canonical(tag)
	name := AliasCatalogName(tag)
	for _, dir := range projectDirs {
		if dir == "" {
			continue
		}
		path := filepath.Join(dir, LocaleDirName, name)
		data, err := os.ReadFile(path)
		if err != nil {
			if os.IsNotExist(err) {
				continue
			}
			return nil, fmt.Errorf("i18n: reading %s: %w", path, err)
		}
		return parseAliasCatalog(path, data)
	}

	path := "locales/" + name
	data, err := localesFS.ReadFile(path)
	if err != nil {
		return nil, nil
	}
	return parseAliasCatalog(path, data)
}

// Canonical maps an alias onto the tag whose file exists. Unknown tags are
// returned unchanged so the caller can decide what to do.
func Canonical(tag string) string {
	if c, ok := alias[strings.ToLower(tag)]; ok {
		return c
	}
	return tag
}

// ProjectDirs returns the default search list, most specific first: the working
// directory, then the enclosing workspace root. Both binaries use this so a
// project's `locales/` override behaves the same for `no` and for the LSP.
func ProjectDirs() []string {
	wd, err := os.Getwd()
	if err != nil {
		return nil
	}
	dirs := []string{wd}
	if root, ok := findWorkspaceRoot(wd); ok && root != wd {
		dirs = append(dirs, root)
	}
	return dirs
}

// findWorkspaceRoot walks up from start looking for workspace.noml.
func findWorkspaceRoot(start string) (string, bool) {
	dir := start
	for {
		if _, err := os.Stat(filepath.Join(dir, pkg.WorkspaceFileName)); err == nil {
			return dir, true
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", false
		}
		dir = parent
	}
}

// Available lists every tag that has a catalog, project-local first, with the
// aliases appended so the resolver can match a bare "zh" request.
func Available(projectDirs []string) []string {
	seen := map[string]bool{}
	var out []string
	add := func(tag string) {
		if tag == "" || tag == "en" || seen[tag] {
			return
		}
		seen[tag] = true
		out = append(out, tag)
	}

	for _, dir := range projectDirs {
		for _, tag := range tagsInDir(dir) {
			add(tag)
		}
	}
	for _, tag := range embeddedTags() {
		add(tag)
	}

	aliases := make([]string, 0, len(alias))
	for a := range alias {
		aliases = append(aliases, a)
	}
	sort.Strings(aliases)
	for _, a := range aliases {
		// `zh-cn` is the lower-case spelling of `zh-CN`, which is already listed;
		// adding it would print the same language twice in a warning.
		if strings.EqualFold(a, alias[a]) {
			continue
		}
		if seen[alias[a]] {
			add(a)
		}
	}
	return out
}

// Load reads the catalog for tag: project overrides first, then the embedded
// copy. A project file REPLACES the embedded one wholesale for that tag rather
// than merging key by key — predictable beats clever when the file is also the
// thing a translator edits.
func Load(projectDirs []string, tag string) (map[string]string, error) {
	tag = Canonical(tag)
	name := LocaleFileName(tag)
	for _, dir := range projectDirs {
		if dir == "" {
			continue
		}
		path := filepath.Join(dir, LocaleDirName, name)
		data, err := os.ReadFile(path)
		if err != nil {
			if os.IsNotExist(err) {
				continue
			}
			return nil, fmt.Errorf("i18n: reading %s: %w", path, err)
		}
		return parseCatalog(path, data)
	}

	path := "locales/" + name
	data, err := localesFS.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("i18n: no catalog for %q", tag)
	}
	return parseCatalog(path, data)
}

// ParseCatalogData turns a `.noml` catalog document into a flat id -> text map.
// It is the same reader Load uses, exported so the generator can inspect the
// committed file it is about to rewrite (to preserve doc translations) without
// going through the embedded copy.
func ParseCatalogData(path string, data []byte) (map[string]string, error) {
	return parseCatalog(path, data)
}

// parseCatalog turns a `.noml` document into a flat id -> text map. Every value
// must be a string: a nested object or array means the file was hand-edited
// wrong, and failing loudly here beats a silent half-loaded catalog.
func parseCatalog(path string, data []byte) (map[string]string, error) {
	m, err := pkg.ParseNomlMap(data)
	if err != nil {
		return nil, fmt.Errorf("i18n: %s: %w", path, err)
	}
	out := make(map[string]string, len(m))
	for k, v := range m {
		s, ok := v.(string)
		if !ok {
			return nil, fmt.Errorf("i18n: %s: value for %q must be a string, got %T", path, k, v)
		}
		out[k] = s
	}
	return out, nil
}

// ParseAliasCatalogData turns a `.noml` alias document into anchor -> row. It is
// the alias twin of ParseCatalogData, exported so the generator can inspect the
// committed file it is about to rewrite.
func ParseAliasCatalogData(path string, data []byte) (map[string]i18n.AliasEntry, error) {
	return parseAliasCatalog(path, data)
}

// parseAliasCatalog reads an alias catalog. It is a separate reader from
// parseCatalog on purpose: a message/doc catalog requires every value to be a
// string (a nested value there means the file was hand-edited wrong), while an
// alias row IS an object. One reader cannot enforce both, and silently
// accepting either shape would make a typo'd alias file load as an empty table.
//
// Every check here is adversarial, because the failure mode is silent: a
// misspelled field name would otherwise drop a row's display name, and a
// non-ASCII keystroke column would simply never match anything at runtime.
func parseAliasCatalog(path string, data []byte) (map[string]i18n.AliasEntry, error) {
	m, err := pkg.ParseNomlMap(data)
	if err != nil {
		return nil, fmt.Errorf("i18n: %s: %w", path, err)
	}
	out := make(map[string]i18n.AliasEntry, len(m))
	for anchor, raw := range m {
		row, ok := raw.(map[string]any)
		if !ok {
			return nil, fmt.Errorf("i18n: %s: value for %q must be an object with alias/keys/enkeys, got %T",
				path, anchor, raw)
		}
		e := i18n.AliasEntry{Anchor: anchor}
		for field, value := range row {
			switch field {
			case AliasFieldAlias:
				list, ok := value.([]any)
				if !ok {
					return nil, fmt.Errorf("i18n: %s: %q: %s must be an array of strings, got %T",
						path, anchor, field, value)
				}
				if len(list) == 0 {
					return nil, fmt.Errorf("i18n: %s: %q: %s must list at least one name",
						path, anchor, field)
				}
				for i, item := range list {
					name, ok := item.(string)
					if !ok || name == "" {
						return nil, fmt.Errorf("i18n: %s: %q: %s[%d] must be a non-empty string, got %T",
							path, anchor, field, i, item)
					}
					e.Alias = append(e.Alias, name)
				}
			case AliasFieldKeys, AliasFieldEnKeys, AliasFieldPinyin, AliasFieldZhuyin:
				s, ok := value.(string)
				if !ok {
					return nil, fmt.Errorf("i18n: %s: %q: %s must be a string, got %T",
						path, anchor, field, value)
				}
				if !isAliasKeyString(s) {
					return nil, fmt.Errorf("i18n: %s: %q: %s must be a non-empty ASCII string of [a-z0-9], got %q",
						path, anchor, field, s)
				}
				switch field {
				case AliasFieldKeys:
					e.Keys = s
				case AliasFieldEnKeys:
					e.EnKeys = s
				case AliasFieldPinyin:
					e.Pinyin = s
				case AliasFieldZhuyin:
					e.Zhuyin = s
				}
			default:
				return nil, fmt.Errorf("i18n: %s: %q: unknown field %q (allowed: %s)",
					path, anchor, field, strings.Join(AliasRequiredFields, ", ")+", "+AliasFieldPinyin+", "+AliasFieldZhuyin)
			}
		}
		for _, field := range AliasRequiredFields {
			missing := (field == AliasFieldAlias && len(e.Alias) == 0) ||
				(field == AliasFieldKeys && e.Keys == "") ||
				(field == AliasFieldEnKeys && e.EnKeys == "")
			if missing {
				return nil, fmt.Errorf("i18n: %s: %q: missing required field %s", path, anchor, field)
			}
		}
		out[anchor] = e
	}
	return out, nil
}

// isAliasKeyString reports whether s is a well-formed keystroke column: ASCII
// `[a-z0-9]`, non-empty. Completion matches these byte for byte against the word
// the editor reports, so anything else is a cell that can never fire.
func isAliasKeyString(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') {
			continue
		}
		return false
	}
	return true
}

// tagsInDir lists the `<tag>.noml` files directly under dir/locales. Doc
// catalogs (`<tag>-doc.noml`) are skipped: they are not tags of their own, and
// listing them would make `Available` claim a language the messages have no
// catalog for.
//
// The file name is lower-case (`zh-cn.noml`) but the tag is not (`zh-CN`), so
// each name goes back through Canonical. A name with no alias entry is returned
// as-is: a project may ship a locale we do not know about.
func tagsInDir(dir string) []string {
	entries, err := os.ReadDir(filepath.Join(dir, LocaleDirName))
	if err != nil {
		return nil
	}
	var out []string
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".noml") ||
			IsDocCatalogName(e.Name()) || IsAliasCatalogName(e.Name()) {
			continue
		}
		out = append(out, Canonical(strings.TrimSuffix(e.Name(), ".noml")))
	}
	sort.Strings(out)
	return out
}
